rules.expression:
sum by (namespace, pod, job, cluster) (
  max by(namespace, pod, job, cluster) (
    kube_pod_status_phase{job!="", phase=~"Pending|Unknown"}
    or
    (
      kube_pod_status_phase{job!="", phase="Running"} == 1
      and on(namespace, pod, cluster)
      kube_pod_status_ready{job!="", condition="true"} == 0
    )
  ) * on(namespace, pod, cluster) group_left() topk by(namespace, pod, cluster) (
    1, max by(namespace, pod, owner_kind, cluster) (kube_pod_owner{owner_kind!="Job"})
  )
) > 0
unless on(namespace, pod, cluster)
kube_pod_status_reason{job!="", reason="SchedulingGated"} == 1

(
  max by(namespace, statefulset, job, cluster) (
    kube_statefulset_status_current_revision{job!=""}
      unless
    kube_statefulset_status_update_revision{job!=""}
  )
    * on(namespace, statefulset, job, cluster)
  (
    kube_statefulset_replicas{job!=""}
      !=
    kube_statefulset_status_replicas_updated{job!=""}
  )
)  and on(namespace, statefulset, job, cluster) (
  changes(kube_statefulset_status_replicas_updated{job!=""}[5m])
    ==
  0
)

(sum by (cluster) (sum by (namespace, cluster) (
    sum by (namespace, pod, cluster) (
        max by (namespace, pod, container, cluster) (
          kube_pod_container_resource_requests{resource="cpu",job!=""}
        ) * on(namespace, pod, cluster) group_left() max by (namespace, pod, cluster) (
          kube_pod_status_phase{phase=~"Pending|Running"} == 1
        )
    )
)) - sum by (cluster) (kube_node_status_allocatable{job!="",resource="cpu"})) > 0

(sum by (cluster) (sum by (namespace, cluster) (
    sum by (namespace, pod, cluster) (
        max by (namespace, pod, container, cluster) (
          kube_pod_container_resource_requests{resource="memory",job!=""}
        ) * on(namespace, pod, cluster) group_left() max by (namespace, pod, cluster) (
          kube_pod_status_phase{phase=~"Pending|Running"} == 1
        )
    )
)) - sum by (cluster) (kube_node_status_allocatable{job!="",resource="memory"})) > 0

sum by(cluster) (
  min without(resource) (kube_resourcequota{job!="", type="hard", resource=~"(cpu|requests.cpu)"})
)
/
sum by(cluster) (
  kube_node_status_allocatable{resource="cpu", job!=""}
) > 1.5

sum by(cluster) (
  min without(resource) (kube_resourcequota{job!="", type="hard", resource=~"(memory|requests.memory)"})
)
/
sum by(cluster) (
  kube_node_status_allocatable{resource="memory", job!=""}
) > 1.5

sum without (id, metrics_path, name, image, endpoint, job, node) (
  topk by (cluster, namespace, pod, container, instance) (1,
    increase(
      container_cpu_cfs_throttled_periods_total{container!="", job!="", }
    [5m])
  )
)
/ on (cluster, namespace, pod, container, instance) group_left
sum without (id, metrics_path, name, image, endpoint, job, node) (
  topk by (cluster, namespace, pod, container, instance) (1,
    increase(
      container_cpu_cfs_periods_total{job!="", }
    [5m])
  )
)
> ( 25 / 100 )

(
  max by (cluster, instance) (
    kubelet_running_pods{job!=""} > 1
  )
  * on (cluster, instance) group_left(node)
  max by (cluster, instance, node) (
    kubelet_node_name{job!=""}
  )
)
/ on (cluster, node) group_left()
max by (cluster, node) (
  kube_node_status_capacity{job!="", resource="pods"} != 1
) > 0.95

sum(rate(kubelet_evictions{job!=""}[15m])) by(cluster, eviction_signal, instance)
* on (cluster, instance) group_left(node)
max by (cluster, instance, node) (
  kubelet_node_name{job!=""}
)
> 0

histogram_quantile(0.99,
  sum by (cluster, instance, le) (
    topk by (cluster, instance, le, operation_type) (1,
      rate(kubelet_pod_worker_duration_seconds_bucket{job!=""}[5m])
    )
  )
)
* on(cluster, instance) group_left(node)
topk by (cluster, instance, node) (1,
  kubelet_node_name{job!=""}
)
> 60
